From Raoult's Law;

\begin{aligned}
& \mathrm{P}_{\text {total }}=\mathrm{P}_1+\mathrm{P}_2=\mathrm{x}_{\mathrm{A}} \mathrm{P}_{\mathrm{A}}^{\circ}+\mathrm{x}_{\mathrm{B}} \mathrm{P}_{\mathrm{B}}^{\circ} \\
& \text { We have, } \mathrm{P}_{\mathrm{A}}^{\circ}=70 \text { torr } \\
& \mathrm{x}_{\mathrm{B}}=0.2 \text { so } \mathrm{x}_{\mathrm{A}}=1-0.2=0.8 \\
& \mathrm{P}_{\text {total }}=84 \text { torr } \\
& \Rightarrow \mathrm{P}_{\mathrm{B}}^{\circ}=\frac{\mathrm{P}_{\text {total }}-\mathrm{x}_{\mathrm{A}} \mathrm{P}_{\mathrm{A}}^{\circ}}{\mathrm{x}_{\mathrm{B}}} \\
& =\frac{84-(0.8 \times 70)}{0.2}=140 \text { torr }
\end{aligned}

$\begin{aligned}
& (1+x)^{101}\left(1-x+x^2\right)^{100} \\
& =(1+x)\left[(1+x)\left(1-x+x^2\right)\right]^{100} \\
& =(1+x)\left(1+x^3\right)^{100}=1\left(1+x^3\right)^{100}+x\left(1+x^3\right)^{100} \\
& \begin{aligned}
\therefore \text { Coefficient of } x^{50} \\
=\left\{1 \times \text { coefficient of } x^{50} \text { in }\left(1+x^3\right)^{100}\right\} \\
\quad+\left\{1 \times \text { coefficient of } x^{49} \text { in }\left(1+x^3\right)^{100}\right\}
\end{aligned}
\end{aligned}\because\left(1+x^3\right)_n$ will contain only powers of $x$ which are multiple of 3 .
$\therefore \quad$ Coefficient of $x^{50}=$ Coefficient of $x^{49}=0$

$\tan y=\cot \left(\frac{\pi}{4}-x\right)\begin{aligned}
\Rightarrow \quad \sec ^2 y \frac{d y}{d x}=-(-1) \operatorname{cosec}^2\left(\frac{\pi}{4}-x\right)
\end{aligned}\begin{aligned}
\Rightarrow \quad \frac{d y}{d x} & =\frac{\operatorname{cosec}^2\left(\frac{\pi}{4}-x\right)}{\sec ^2 y} \\
& =\frac{\operatorname{cosec}^2\left(\frac{\pi}{4}-x\right)}{1+\tan ^2 y}=\frac{\operatorname{cosec}^2\left(\frac{\pi}{4}-x\right)}{1+\tan ^2\left(\frac{\pi}{4}-x\right)} .
\end{aligned}$

